import { execSync } from "child_process";

export interface WindowsProxySettings {
  proxyUrl: string;
  noProxy: string[];
}

function getRegistryValue(key: string, valueName: string): string | undefined {
  try {
    // /v 表示获取指定键
    const cmd = `reg query "${key}" /v ${valueName}`;
    const output = execSync(cmd, { encoding: "utf8" });
    // 查找 REG_SZ 和 REG_DWORD 的值（泛用正则）
    const match = output.match(new RegExp(`${valueName}\\s+REG_[^\\s]+\\s+(.+)`, "i"));
    if (match) {
      return match[1].trim();
    }
  } catch {
    // 没有该值或命令错误
  }
  return undefined;
}

/**
 * 检查并解析Windows系统代理设置
 */
export async function getWindowsSystemProxy(): Promise<WindowsProxySettings | undefined> {
  if (process.platform === "darwin") {
    throw new Error("Can't detect windows system proxy on non-Windows platform");
  } else if (process.platform === "win32") {
    const regKey = "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings";
    const proxyEnabled = getRegistryValue(regKey, "ProxyEnable");
    const proxyServer = getRegistryValue(regKey, "ProxyServer");

    // ProxyEnable=1表示开启
    if (proxyEnabled !== "0x1" || !proxyServer) return undefined;

    // ProxyOverride 是要跳过代理的主机列表（分号分隔）
    const proxyOverride = getRegistryValue(regKey, "ProxyOverride");
    const noProxy = proxyOverride ? proxyOverride.split(";") : [];
    noProxy.push("localhost", "127.0.0.1", "::1"); // 默认不代理本地请求

    // ProxyServer 格式处理
    const proxyConfigString = proxyServer;

    if (proxyConfigString.startsWith("http://") || proxyConfigString.startsWith("https://")) {
      return {
        proxyUrl: proxyConfigString,
        noProxy: noProxy,
      };
    } else if (proxyConfigString.includes("=")) {
      // 多协议配置如 http=host;https=host;socks=host
      const proxies: Record<string, string> = {};
      proxyConfigString.split(";").forEach((pair) => {
        const [proto, host] = pair.split("=");
        if (proto && host) proxies[proto] = host;
      });

      const proxyUrl = proxies["http"]
        ? `http://${proxies["http"]}`
        : proxies["socks"]
        ? `socks://${proxies["socks"]}`
        : proxies["https"]
        ? `http://${proxies["https"]}`
        : undefined;

      if (!proxyUrl) return undefined;

      return {
        proxyUrl,
        noProxy,
      };
    } else {
      return {
        proxyUrl: `http://${proxyConfigString}`,
        noProxy,
      };
    }
  } else {
    const { HTTPS_PROXY, https_proxy, HTTP_PROXY, http_proxy, NO_PROXY, no_proxy } = process.env;

    const proxyUrl = HTTPS_PROXY || HTTP_PROXY || https_proxy || http_proxy;

    if (!proxyUrl) return undefined;

    const noProxy = !!(NO_PROXY || no_proxy) ? (NO_PROXY || no_proxy)!.split(",") : [];

    return {
      proxyUrl,
      noProxy,
    };
  }
}

interface IProxyInfo {
  url: string;
  noProxy: string;
}
export const setProxyEnvironment = (proxyInfo: IProxyInfo) => {
  if (proxyInfo.url === "") {
    delete process.env.HTTP_PROXY;
    delete process.env.HTTPS_PROXY;
    delete process.env.grpc_proxy;
    delete process.env.http_proxy;
    delete process.env.https_proxy;
    delete process.env.no_proxy;

    delete process.env.SOCKS_PROXY;
    delete process.env.ALL_PROXY;
  } else {
    process.env.grpc_proxy = proxyInfo.url;
    process.env.HTTP_PROXY = proxyInfo.url;
    process.env.HTTPS_PROXY = proxyInfo.url;
    process.env.http_proxy = proxyInfo.url;
    process.env.https_proxy = proxyInfo.url;
    process.env.no_proxy = proxyInfo.noProxy;
    if (proxyInfo.url.startsWith("socks")) {
      process.env.SOCKS_PROXY = proxyInfo.url;
      process.env.ALL_PROXY = proxyInfo.url;
    }
  }
};
